{"file_path": "src/lib/db-helpers.ts", "initial_content": "/**
 * Database helper functions for PostgreSQL queries
 * Replaces Firebase operations with Drizzle ORM queries
 */

import { db } from '@/db';
import {
  users,
  projects,
  sections,
  templates,
  agents,
  transactions,
  notifications,
  generation_history,
  audit_logs,
  features,
  device_tokens,
  settings,
  session_logs,
} from '@/db/schema';
import { eq, desc, and, gte, lte, like, inArray } from 'drizzle-orm';
import type { UserProfile } from '@/lib/models/user';
import type { ProjectProperties } from '@/lib/models';

// ============================================================================
// USER OPERATIONS
// ============================================================================

export async function getUserById(userId: number) {
  const [user] = await db.select().from(users).where(eq(users.id, userId));
  return user || null;
}

export async function getUserByEmail(email: string) {
  const [user] = await db.select().from(users).where(eq(users.email, email));
  return user || null;
}

export async function getAllUsers(limit = 50, offset = 0) {
  return await db
    .select()
    .from(users)
    .limit(limit)
    .offset(offset)
    .orderBy(desc(users.createdAt));
}

export async function createUser(userData: Omit<UserProfile, 'id' | 'createdAt' | 'updatedAt'>) {
  const [newUser] = await db.insert(users).values(userData).returning();
  return newUser;
}

export async function updateUser(userId: number, updates: Partial<UserProfile>) {
  const [updated] = await db
    .update(users)
    .set({ ...updates, updatedAt: new Date() })
    .where(eq(users.id, userId))
    .returning();
  return updated;
}

export async function deleteUser(userId: number) {
  return await db.delete(users).where(eq(users.id, userId));
}

export async function getUserCredits(userId: number) {
  const [user] = await db.select({ credits: users.credits }).from(users).where(eq(users.id, userId));
  return user?.credits || 0;
}

export async function updateUserCredits(userId: number, newCredits: number) {
  return await db.update(users).set({ credits: newCredits }).where(eq(users.id, userId));
}

// ============================================================================
// PROJECT OPERATIONS
// ============================================================================

export async function getProjectById(projectId: number) {
  const [project] = await db.select().from(projects).where(eq(projects.id, projectId));
  return project || null;
}

export async function getUserProjects(userId: number) {
  return await db
    .select()
    .from(projects)
    .where(eq(projects.userId, userId))
    .orderBy(desc(projects.updatedAt));
}

export async function createProject(projectData: Omit<ProjectProperties, 'id' | 'createdAt' | 'updatedAt'>) {
  const [newProject] = await db.insert(projects).values(projectData).returning();
  return newProject;
}

export async function updateProject(projectId: number, updates: Partial<ProjectProperties>) {
  const [updated] = await db
    .update(projects)
    .set({ ...updates, updatedAt: new Date() })
    .where(eq(projects.id, projectId))
    .returning();
  return updated;
}

export async function deleteProject(projectId: number) {
  return await db.delete(projects).where(eq(projects.id, projectId));
}

// ============================================================================
// SECTION OPERATIONS
// ============================================================================

export async function getSectionsByProjectId(projectId: number) {
  return await db
    .select()
    .from(sections)
    .where(eq(sections.projectId, projectId))
    .orderBy(sections.order);
}

export async function getSectionById(sectionId: number) {
  const [section] = await db.select().from(sections).where(eq(sections.id, sectionId));
  return section || null;
}

export async function createSection(sectionData: any) {
  const [newSection] = await db.insert(sections).values(sectionData).returning();
  return newSection;
}

export async function updateSection(sectionId: number, updates: any) {
  const [updated] = await db
    .update(sections)
    .set({ ...updates, updatedAt: new Date() })
    .where(eq(sections.id, sectionId))
    .returning();
  return updated;
}

export async function deleteSection(sectionId: number) {
  return await db.delete(sections).where(eq(sections.id, sectionId));
}

// ============================================================================
// TEMPLATE OPERATIONS
// ============================================================================

export async function getAllTemplates() {
  return await db.select().from(templates).orderBy(desc(templates.createdAt));
}

export async function getTemplateById(templateId: number) {
  const [template] = await db.select().from(templates).where(eq(templates.id, templateId));
  return template || null;
}

export async function getTemplatesByCategory(category: string) {
  return await db.select().from(templates).where(eq(templates.category, category));
}

export async function createTemplate(templateData: any) {
  const [newTemplate] = await db.insert(templates).values(templateData).returning();
  return newTemplate;
}

export async function updateTemplate(templateId: number, updates: any) {
  const [updated] = await db
    .update(templates)
    .set({ ...updates, updatedAt: new Date() })
    .where(eq(templates.id, templateId))
    .returning();
  return updated;
}

export async function deleteTemplate(templateId: number) {
  return await db.delete(templates).where(eq(templates.id, templateId));
}

// ============================================================================
