// ============================================================================

export async function getAllAgents() {
  return await db.select().from(agents).orderBy(desc(agents.createdAt));
}

export async function getAgentById(agentId: number) {
  const [agent] = await db.select().from(agents).where(eq(agents.id, agentId));
  return agent || null;
}

export async function getAgentsByCategory(category: string) {
  return await db.select().from(agents).where(eq(agents.category, category));
}

export async function createAgent(agentData: any) {
  const [newAgent] = await db.insert(agents).values(agentData).returning();
  return newAgent;
}

export async function updateAgent(agentId: number, updates: any) {
  const [updated] = await db
    .update(agents)
    .set(updates)
    .where(eq(agents.id, agentId))
    .returning();
  return updated;
}

export async function deleteAgent(agentId: number) {
  return await db.delete(agents).where(eq(agents.id, agentId));
}

// ============================================================================
// TRANSACTION OPERATIONS
// ============================================================================

export async function getUserTransactions(userId: number, limit = 50, offset = 0) {
  return await db
    .select()
    .from(transactions)
    .where(eq(transactions.userId, userId))
    .limit(limit)
    .offset(offset)
    .orderBy(desc(transactions.createdAt));
}

export async function createTransaction(transactionData: any) {
  const [newTransaction] = await db.insert(transactions).values(transactionData).returning();
  return newTransaction;
}

export async function getTransactionById(transactionId: number) {
  const [transaction] = await db.select().from(transactions).where(eq(transactions.id, transactionId));
  return transaction || null;
}

// ============================================================================
// NOTIFICATION OPERATIONS
// ============================================================================

export async function getUserNotifications(userId: number, limit = 50, offset = 0) {
  return await db
    .select()
    .from(notifications)
    .where(eq(notifications.userId, userId))
    .limit(limit)
    .offset(offset)
    .orderBy(desc(notifications.createdAt));
}

export async function createNotification(notificationData: any) {
  const [newNotification] = await db.insert(notifications).values(notificationData).returning();
  return newNotification;
}

export async function markNotificationAsRead(notificationId: number) {
  return await db.update(notifications).set({ read: true }).where(eq(notifications.id, notificationId));
}

export async function deleteNotification(notificationId: number) {
  return await db.delete(notifications).where(eq(notifications.id, notificationId));
}

// ============================================================================
// GENERATION HISTORY OPERATIONS
// ============================================================================

export async function logGeneration(generationData: any) {
  const [log] = await db.insert(generation_history).values(generationData).returning();
  return log;
}

export async function getUserGenerationHistory(userId: number, limit = 50, offset = 0) {
  return await db
    .select()
    .from(generation_history)
    .where(eq(generation_history.userId, userId))
    .limit(limit)
    .offset(offset)
    .orderBy(desc(generation_history.createdAt));
}

export async function getGenerationStats(userId: number) {
  const result = await db
    .select()
    .from(generation_history)
    .where(eq(generation_history.userId, userId));

  return {
    totalGenerations: result.length,
    completedGenerations: result.filter(g => g.status === 'completed').length,
    failedGenerations: result.filter(g => g.status === 'failed').length,
    totalCreditsUsed: result.reduce((sum, g) => sum + (g.creditsUsed || 0), 0),
    totalTokensUsed: result.reduce((sum, g) => sum + (g.tokensUsed || 0), 0),
  };
}

// ============================================================================
// AUDIT LOG OPERATIONS
// ============================================================================

