    .limit(limit)
    .offset(offset)
    .orderBy(desc(audit_logs.createdAt));
}

// ============================================================================
// FEATURE OPERATIONS
// ============================================================================

export async function getFeatureByName(name: string) {
  const [feature] = await db.select().from(features).where(eq(features.name, name));
  return feature || null;
}

export async function getAllFeatures() {
  return await db.select().from(features);
}

export async function isFeatureEnabled(name: string) {
  const feature = await getFeatureByName(name);
  return feature?.enabled || false;
}

export async function createFeature(featureData: any) {
  const [newFeature] = await db.insert(features).values(featureData).returning();
  return newFeature;
}

export async function updateFeature(featureId: number, updates: any) {
  const [updated] = await db
    .update(features)
    .set({ ...updates, updatedAt: new Date() })
    .where(eq(features.id, featureId))
    .returning();
  return updated;
}

// ============================================================================
// DEVICE TOKEN OPERATIONS
// ============================================================================

export async function getUserDeviceTokens(userId: number) {
  return await db
    .select()
    .from(device_tokens)
    .where(and(eq(device_tokens.userId, userId), eq(device_tokens.active, true)));
}

export async function addDeviceToken(userId: number, token: string, platform: string) {
  try {
    const [newToken] = await db
      .insert(device_tokens)
      .values({ userId, token, platform })
      .returning();
    return newToken;
  } catch (error: any) {
    if (error.code === '23505') {
      // Unique constraint violation - token already exists
      return await db
        .update(device_tokens)
        .set({ active: true, updatedAt: new Date() })
        .where(eq(device_tokens.token, token))
        .returning()
        .then(result => result[0]);
    }
    throw error;
  }
}

export async function removeDeviceToken(token: string) {
  return await db.delete(device_tokens).where(eq(device_tokens.token, token));
}

// ============================================================================
// SETTINGS OPERATIONS
// ============================================================================

export async function getUserSetting(userId: number | null, key: string) {
  const [setting] = await db
    .select()
    .from(settings)
    .where(and(eq(settings.userId, userId), eq(settings.key, key)));
  return setting?.value || null;
}

export async function setUserSetting(userId: number | null, key: string, value: any) {
  const existing = await db
    .select()
    .from(settings)
    .where(and(eq(settings.userId, userId), eq(settings.key, key)));

  if (existing.length > 0) {
    return await db
      .update(settings)
      .set({ value, updatedAt: new Date() })
      .where(and(eq(settings.userId, userId), eq(settings.key, key)))
      .returning();
  } else {
    return await db.insert(settings).values({ userId, key, value }).returning();
  }
}

// ============================================================================
// SESSION LOG OPERATIONS
// ============================================================================

export async function startSessionLog(userId: number, sessionId: string, ipAddress?: string, userAgent?: string) {
  const [log] = await db
    .insert(session_logs)
    .values({ userId, sessionId, ipAddress, userAgent })
    .returning();
  return log;
}

export async function endSessionLog(sessionId: string) {
  return await db
    .update(session_logs)
    .set({ endedAt: new Date() })
    .where(eq(session_logs.sessionId, sessionId));
}

export async function getUserActiveSessions(userId: number) {
  return await db
    .select()
    .from(session_logs)
    .where(and(eq(session_logs.userId, userId), eq(session_logs.endedAt, null)));
}

// ============================================================================
// DASHBOARD/ANALYTICS OPERATIONS
// ============================================================================

export async function getDashboardStats() {
  const totalUsers = await db.select().from(users);
  const totalGenerations = await db.select().from(generation_history);
  const pendingTransactions = await db
    .select()
    .from(transactions)
    .where(eq(transactions.status, 'pending'));

  return {
    totalUsers: totalUsers.length,
    totalGenerations: totalGenerations.length,
    pendingPayments: pendingTransactions.length,
    generationsThisMonth: totalGenerations.filter(g => {
      const monthAgo = new Date();
      monthAgo.setMonth(monthAgo.getMonth() - 1);
      return new Date(g.createdAt || '') > monthAgo;
    }).length,
  };
}

export async function getAgentUsageStats() {
  const generations = await db.select().from(generation_history);
  const agentUsage: Record<string, number> = {};

  generations.forEach(g => {
    if (g.agentId) {
      agentUsage[g.agentId] = (agentUsage[g.agentId] || 0) + 1;
    }
  });

  return Object.entries(agentUsage)
    .map(([agentId, count]) => ({ name: agentId, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10);
}

export async function getRecentActivity(limit = 20) {
  const logs = await db
    .select()
    .from(generation_history)
    .orderBy(desc(generation_history.createdAt))
    .limit(limit);

  return logs.map(log => ({
    id: String(log.id),
    userId: log.userId,
    agentId: log.agentId,
    createdAt: log.createdAt?.toISOString() || '',
    input: log.prompt,
    output: log.output,
  }));
}
"}

