'use server';

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth/authOptions';
import { getUserById, updateUserCredits, createTransaction, logAuditEvent } from '@/lib/db-helpers';
import type { NextRequest } from 'next/server';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user || session.user.role !== 'admin') {
      return Response.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { userId, credits, reason } = await request.json();

    if (!userId || !credits || credits <= 0) {
      return Response.json(
        { error: 'Invalid userId or credits amount' },
        { status: 400 }
      );
    }

    // Get current user credits
    const user = await getUserById(userId);
    if (!user) {
      return Response.json({ error: 'User not found' }, { status: 404 });
    }

    // Update credits
    const newCredits = (user.credits || 0) + credits;
    await updateUserCredits(userId, newCredits);

    // Log transaction
    await createTransaction({
      userId,
      type: 'gift',
      credits,
      description: reason || 'Gift credits from admin',
      status: 'completed',
    });

    // Log audit event
    await logAuditEvent({
      userId: session.user.id,
      action: 'gift_credits',
      entityType: 'user',
      entityId: String(userId),
      changes: { creditsAdded: credits, newBalance: newCredits },
      ipAddress: request.headers.get('x-forwarded-for') || 'unknown',
    });

    return Response.json({ 
      message: 'Credits gifted successfully',
      newBalance: newCredits
    });
  } catch (error) {
    console.error('Error gifting credits:', error);
    return Response.json(
      { error: 'Failed to gift credits' },
      { status: 500 }
    );
  }
}
